# Toy write-ahead journal: disk holds block values, the journal holds intents.
def run(crash_at):
    disk = {"A": 10, "B": 20}
    journal = []
    steps = ["log A=15", "log B=15", "commit", "checkpoint"]
    for i, s in enumerate(steps):
        if i == crash_at:
            break
        if s.startswith("log"):
            journal.append((s[4], int(s[6:])))
        elif s == "commit":
            journal.append("COMMIT")
        else:
            for k, v in journal[:-1]:
                disk[k] = v      # copy logged blocks to home locations
    # recovery: replay only if a commit record exists (replay is idempotent)
    if "COMMIT" in journal:
        for k, v in journal[:-1]:
            disk[k] = v
    return disk

for c, label in [(1, "crash after 1 log record"), (2, "crash before commit"),
                 (3, "crash after commit, before checkpoint"), (4, "no crash")]:
    d = run(c)
    print("%-40s -> A=%d B=%d (sum=%d)" % (label, d["A"], d["B"], d["A"] + d["B"]))

