import java.util.*;
public class Main {
    public static void main(String[] args) {
        int head = 53, max = 199;
        int[] q = {98, 183, 37, 122, 14, 124, 65, 67};
        System.out.println("head=" + head + " queue=" + Arrays.toString(q));
        // FCFS: serve in arrival order
        int fcfs = 0, pos = head;
        for (int r : q) { fcfs += Math.abs(r - pos); pos = r; }
        // SSTF: always pick the nearest pending request
        boolean[] done = new boolean[q.length];
        int sstf = 0; pos = head;
        for (int n = 0; n < q.length; n++) {
            int best = -1;
            for (int i = 0; i < q.length; i++)
                if (!done[i] && (best < 0 || Math.abs(q[i] - pos) < Math.abs(q[best] - pos))) best = i;
            sstf += Math.abs(q[best] - pos); pos = q[best]; done[best] = true;
        }
        // SCAN/LOOK going up first, then back down to the lowest request
        int hi = Arrays.stream(q).max().getAsInt(), lo = Arrays.stream(q).min().getAsInt();
        int scan = (max - head) + (max - lo);   // SCAN runs to the disk edge
        int look = (hi - head) + (hi - lo);     // LOOK turns at the last request
        System.out.println("FCFS=" + fcfs + " SSTF=" + sstf + " SCAN=" + scan + " LOOK=" + look);
    }
}

