using namespace std;
int main() {
    int head = 53, edge = 199;
    vector<int> q = {98, 183, 37, 122, 14, 124, 65, 67};
    cout << "head=" << head << " queue=[";
    for (size_t i = 0; i < q.size(); i++) cout << (i ? ", " : "") << q[i];
    cout << "]" << endl;
    // FCFS: serve in arrival order
    int fcfs = 0, pos = head;
    for (int r : q) { fcfs += abs(r - pos); pos = r; }
    // SSTF: always pick the nearest pending request
    vector<int> pending = q;
    int sstf = 0; pos = head;
    while (!pending.empty()) {
        size_t bi = 0;
        for (size_t i = 1; i < pending.size(); i++)
            if (abs(pending[i] - pos) < abs(pending[bi] - pos)) bi = i;
        sstf += abs(pending[bi] - pos); pos = pending[bi];
        pending.erase(pending.begin() + bi);
    }
    // SCAN/LOOK going up first, then back down to the lowest request
    int hi = *max_element(q.begin(), q.end()), lo = *min_element(q.begin(), q.end());
    int scan = (edge - head) + (edge - lo);   // SCAN runs to the disk edge
    int look = (hi - head) + (hi - lo);       // LOOK turns at the last request
    cout << "FCFS=" << fcfs << " SSTF=" << sstf << " SCAN=" << scan << " LOOK=" << look << endl;
}

