using System.Linq;
class Program {
    static void Main() {
        int head = 53, edge = 199;
        int[] q = {98, 183, 37, 122, 14, 124, 65, 67};
        Console.WriteLine("head=" + head + " queue=[" + string.Join(", ", q) + "]");
        // FCFS: serve in arrival order
        int fcfs = 0, pos = head;
        foreach (int r in q) { fcfs += Math.Abs(r - pos); pos = r; }
        // SSTF: always pick the nearest pending request
        List<int> pending = new List<int>(q);
        int sstf = 0; pos = head;
        while (pending.Count > 0) {
            int bi = 0;
            for (int i = 1; i < pending.Count; i++)
                if (Math.Abs(pending[i] - pos) < Math.Abs(pending[bi] - pos)) bi = i;
            sstf += Math.Abs(pending[bi] - pos); pos = pending[bi];
            pending.RemoveAt(bi);
        }
        // SCAN/LOOK going up first, then back down to the lowest request
        int hi = q.Max(), lo = q.Min();
        int scan = (edge - head) + (edge - lo);   // SCAN runs to the disk edge
        int look = (hi - head) + (hi - lo);       // LOOK turns at the last request
        Console.WriteLine("FCFS=" + fcfs + " SSTF=" + sstf + " SCAN=" + scan + " LOOK=" + look);
    }
}

