public class Main {
    static String bits(int v) { return String.format("%3s", Integer.toBinaryString(v)).replace(' ', '0'); }
    public static void main(String[] args) {
        int d0 = 0b101, d1 = 0b011, d2 = 0b110;
        int p = d0 ^ d1 ^ d2;                  // parity written for the stripe
        System.out.println("D0=" + bits(d0) + " D1=" + bits(d1) + " D2=" + bits(d2) + " P=" + bits(p));
        // disk 1 fails: XOR of every survivor, parity included, gives it back
        int rebuilt = d0 ^ d2 ^ p;
        System.out.println("D1 lost, rebuilt = " + bits(rebuilt) + " ok=" + (rebuilt == d1));
        // small write: new parity from old data, new data and old parity only
        int newD0 = 0b111;
        int newP = p ^ d0 ^ newD0;
        System.out.println("small write P=" + bits(newP) + " full recompute=" + bits(newD0 ^ d1 ^ d2));
    }
}

